update public.products set description='Frozen hard chicken leg portions, commonly called Orobo in the Nigerian frozen-food market, suited to stews, soups, grilling, roasting and frying.', handling_protocols=array['Keep frozen until ready to thaw and keep raw poultry separated from other foods.','Thaw safely in the refrigerator where possible and do not wash the raw chicken.','Cook the thickest part to at least 74°C / 165°F without measuring directly against the bone.']::text[], storage_tips=array['Keep at about -18°C or below.','For best frozen quality, use within about 6–9 months.','Once thawed in the refrigerator, cook within 1–2 days.']::text[] where name='Frozen Hard Chicken Legs (Orobo)' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Chicken gizzard is the firm muscular digestive organ of the chicken, commonly cooked in stews, peppered dishes, rice dishes and other meals where a chewy texture is desired.', handling_protocols=array['Keep raw gizzard cold and separated from ready-to-eat foods.','Handle on clean surfaces and clean hands and utensils thoroughly afterwards.','Cook thoroughly to at least 74°C / 165°F.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','If frozen, keep at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Chicken Gizzard' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
